class EnvVarCheck
{
    void CheckFlag()
    {
        // .NET 9 breaking change: On Linux, GetEnvironmentVariable now returns ""
        // for empty env vars instead of null (.NET 8 bug treated them as unset).
        // This means null now reliably means "not set" and "" means "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (val is null)
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
        else if (val.Length == 0)
        {
            Console.WriteLine("MY_FLAG explicitly empty");
        }
        else
        {
            Console.WriteLine($"MY_FLAG = {val}");
        }
    }
}

